const text = String($('Fetch CNB').first().json.data || $('Fetch CNB').first().json);
const schemaDoc = $input.first().json;
const cols = (schemaDoc.columns) || (schemaDoc.data && schemaDoc.data.schema && schemaDoc.data.schema.columns) || (schemaDoc.schema && schemaDoc.schema.columns) || [];
const keys = cols.map(c => c.key);
const required = cols.filter(c => c.required).map(c => c.key);
const lines = text.split(/\n/).map(s => s.trim()).filter(Boolean);
const dateParts = lines[0].split(/\s+/)[0].split('.');
const date = `${dateParts[2]}-${dateParts[1].padStart(2,'0')}-${dateParts[0].padStart(2,'0')}`;
const hi = lines.findIndex(l => l.startsWith('země|') || l.startsWith('zeme|'));
const rows = [];
for (const ln of lines.slice(hi + 1)) {
  const p = ln.split('|');
  const amount = Number(p[2]);
  const code = String(p[3]).trim().toUpperCase();
  const rate = Number(String(p[4]).replace(',', '.').replace(/ /g,'')) / amount;
  // estate date columns hold EPOCH SECONDS (digest importers' _epoch convention);
  // KEAP refuses ISO here ('expected epoch seconds', measured 2026-09-21).
  const epoch = Math.floor(Date.parse(date + 'T00:00:00Z') / 1000);
  const raw = { slug: `${date}-${code}`, date: epoch, currency: code, amount: 1, rate: Math.round(rate * 1e6) / 1e6 };
  for (const k of required) { if (!(k in raw)) throw new Error('missing ' + k); }
  rows.push(Object.fromEntries(keys.filter(k => k in raw).map(k => [k, raw[k]])));
}
return rows.map(json => ({ json }));
